import { expect, test } from "@playwright/test";

import {
  getEncounterOverviewUrl,
  getEncounterQuestionnaireUrl,
  saveRecording,
} from "../../support/care";
import { installCursor, Pointer } from "../../support/pointer";

// Records "How to Record a Symptom" on the fixture encounter, which stays the
// patient's active encounter for the rest of the Condition module recordings.
const PAUSE = 900;

// Clean, short SNOMED CT findings that read well in a recording. Kept disjoint from
// the pools used by the other Condition flows so re-runs never collide on the
// "Symptom already exists!" duplicate check.
const SYMPTOM_OPTIONS = [
  "Chronic pain",
  "Acute left-sided ulcerative colitis",
  "Allergy to hydrogen peroxide",
  "Renal scarring due to vesicoureteral reflux",
];

test("How to Record a Symptom", async ({ page }) => {
  const symptomName = faker.helpers.arrayElement(SYMPTOM_OPTIONS);
  const encounterUrl = getEncounterOverviewUrl();
  const questionnaireUrl = getEncounterQuestionnaireUrl("symptom");

  await installCursor(page);
  const pointer = new Pointer(page);

  await test.step("1. Open the symptom screen", async () => {
    await page.goto(encounterUrl);
    await expect(page.getByRole("tab", { name: "Overview" })).toBeVisible();
    const editSymptoms = page.locator('a[href$="/questionnaire/symptom"]');
    await pointer.reset();
    await page.waitForTimeout(PAUSE);
    await pointer.click(editSymptoms);
    await page.waitForURL(/\/questionnaire\/symptom/);
    await page.waitForTimeout(PAUSE);
  });

  await test.step("2. Start a new symptom", async () => {
    const addSymptom = page
      .getByRole("combobox")
      .filter({ hasText: /Add (another )?Symptom/i });
    await pointer.click(addSymptom);
    await page.waitForTimeout(PAUSE);
  });

  await test.step("3. Search for the symptom", async () => {
    await page.getByPlaceholder(/Add (another )?Symptom/i).fill(symptomName);
    await page.waitForTimeout(PAUSE);
  });

  await test.step("4. Select the term", async () => {
    await pointer.click(
      page.getByRole("option", { name: symptomName, exact: true }),
    );
    const symptomRow = page.getByRole("row", { name: symptomName });
    await expect(symptomRow).toBeVisible();
    await page.waitForTimeout(PAUSE);
  });

  await test.step("5. Change the values", async () => {
    const symptomRow = page.getByRole("row", { name: symptomName });
    await pointer.click(symptomRow.getByRole("cell").nth(3));
    await pointer.click(page.getByRole("option", { name: "Mild", exact: true }));
    await page.waitForTimeout(PAUSE);
  });

  await test.step("8. Submit", async () => {
    await pointer.click(page.getByRole("button", { name: "Submit" }));
    await expect(
      page.getByText("Questionnaire submitted successfully"),
    ).toBeVisible();
  });

  await page.waitForTimeout(2500);

  await saveRecording(
    page,
    "Clinical/Condition/media/1. Record a symptom.mp4",
  );
});
"}

