{"content": "import { faker } from "@faker-js/faker";
import { expect, test } from "@playwright/test";

import {
  getEncounterOverviewUrl,
  getFacilityId,
  getPatientHomeUrl,
  getPatientId,
  saveRecording,
} from "../../support/care";
import { installCursor, Pointer } from "../../support/pointer";

// Records "How to Add a Symptom or Diagnosis from Past Records". The picker needs a
// record from an encounter other than the current one, so this spec first creates a
// throwaway earlier encounter and records one symptom on it through an unrecorded
// page (no saveRecording call, so no video is produced for that page). The visible,
// recorded steps below then pull that symptom into the current fixture encounter.
const PAUSE = 900;

// Disjoint from the pools used by the other Condition flows.
const PRIOR_SYMPTOM_OPTIONS = [
  "Small bowel enteroscopy normal",
  "Venous ulcer of toe of left foot",
  "Chronic respiratory failure due to obstructive sleep apnoea",
];

test("How to Add a Symptom or Diagnosis from Past Records", async ({
  page,
  context,
}) => {
  const facilityId = getFacilityId();
  const patientId = getPatientId();
  const priorSymptomName = faker.helpers.arrayElement(PRIOR_SYMPTOM_OPTIONS);

  // --- Unrecorded prep: create an earlier encounter with a symptom on it ---
  const prepPage = await context.newPage();
  await prepPage.goto(await getPatientHomeUrl());
  await prepPage.getByRole("button", { name: "Create Encounter" }).click();
  await prepPage.getByRole("button", { name: "Ambulatory" }).click();
  await prepPage
    .getByRole("button", { name: "Create Encounter" })
    .last()
    .click();
  await prepPage.waitForURL(/\/encounter\/[^/]+\/updates/);
  const priorEncounterId = prepPage
    .url()
    .match(/\/encounter\/([^/]+)\/updates/)![1];

  await prepPage.goto(
    `/facility/${facilityId}/patient/${patientId}/encounter/${priorEncounterId}/questionnaire/symptom`,
  );
  await prepPage
    .getByRole("combobox")
    .filter({ hasText: /Add (another )?Symptom/i })
    .click();
  await prepPage
    .getByPlaceholder(/Add (another )?Symptom/i)
    .fill(priorSymptomName);
  await prepPage
    .getByRole("option", { name: priorSymptomName, exact: true })
    .click();
  await prepPage.getByRole("button", { name: "Submit" }).click();
  await expect(
    prepPage.getByText("Questionnaire submitted successfully"),
  ).toBeVisible();
  await prepPage.close();
  // --- End of unrecorded prep ---

  const encounterUrl = getEncounterOverviewUrl();
  await installCursor(page);
  const pointer = new Pointer(page);

  await test.step("1. Open the symptom screen or the diagnosis screen", async () => {
    await page.goto(encounterUrl);
    await expect(page.getByRole("tab", { name: "Overview" })).toBeVisible();
    const editSymptoms = page.locator('a[href$="/questionnaire/symptom"]');
    await pointer.reset();
    await page.waitForTimeout(PAUSE);
    await pointer.click(editSymptoms);
    await page.waitForURL(/\/questionnaire\/symptom/);
    await page.waitForTimeout(PAUSE);
  });

  await test.step("2. Open the past records dialog", async () => {
    await pointer.click(page.getByRole("button", { name: "Symptom History" }));
    const dialog = page.getByRole("dialog", { name: "Past Symptoms" });
    await expect(dialog).toBeVisible();
    await page.waitForTimeout(PAUSE);
  });

  await test.step("3. Select the records", async () => {
    const dialog = page.getByRole("dialog", { name: "Past Symptoms" });
    const row = dialog
      .locator('[data-slot="table-body"] tr')
      .filter({ hasText: priorSymptomName });
    await pointer.click(row.getByRole("checkbox"));
    await page.waitForTimeout(PAUSE);
  });

  await test.step("4. Add the records", async () => {
    const dialog = page.getByRole("dialog", { name: "Past Symptoms" });
    await pointer.click(dialog.getByRole("button", { name: "Add Selected" }));
    await expect(dialog).toBeHidden();
    await page.waitForTimeout(PAUSE);
  });

  await test.step("5. Review and submit", async () => {
    await pointer.click(page.getByRole("button", { name: "Submit" }));
    await expect(
      page.getByText("Questionnaire submitted successfully"),
    ).toBeVisible();
  });

  await page.waitForTimeout(2500);

  await saveRecording(
    page,
    "Clinical/Condition/media/3. Add a symptom or diagnosis from past records.mp4",
  );
});
", "filePath": "/Users/rithviknishad/ohc.network/care_docs/recordings/Clinical/Condition/3. Add a symptom or diagnosis from past records.demo.ts"}

